namespace Lab04d;

public class Bai3CafeForm : Form
{
    TextBox txtTen = new(); TextBox txtSoKhach = new(); CheckBox chkSinhVien = new(); RadioButton rdoCafeDen = new(); RadioButton rdoCafeDa = new(); RadioButton rdoCafeSua = new(); RadioButton rdoCafeSuaDa = new(); RadioButton rdoCafeKem = new(); CheckBox chkBanhTrung = new(); CheckBox chkBanhCa = new(); CheckBox chkMiTomTrung = new(); CheckBox chkMiXaoBo = new(); CheckBox chkMiCay = new(); Button btnTinhTien = new(); Button btnNhapLai = new(); Button btnThanhToan = new(); TextBox txtTongKhach = new(); TextBox txtTongTien = new(); int tongKhach; decimal tongTien; decimal tienHienTai;
    public Bai3CafeForm()
    {
        Text = "Cafe Sinh Viên"; StartPosition = FormStartPosition.CenterParent;
        TableLayoutPanel content = UiLayout.CreateContent(this, new Size(820, 760), new Size(650, 620)); content.ColumnCount = 1; content.RowCount = 7; content.RowStyles.Add(new RowStyle(SizeType.AutoSize)); for (int i = 0; i < 5; i++) content.RowStyles.Add(new RowStyle(SizeType.AutoSize)); content.RowStyles.Add(new RowStyle(SizeType.Percent, 100)); content.Controls.Add(UiLayout.Title("CAFE SINH VIÊN"), 0, 0);
        TableLayoutPanel customer = UiLayout.Fields(3, 30); UiLayout.AddField(customer, 0, "Tên khách hàng:", txtTen); UiLayout.AddField(customer, 1, "Số khách hàng:", txtSoKhach); chkSinhVien.Text = "Sinh viên?"; chkSinhVien.AutoSize = true; customer.Controls.Add(chkSinhVien, 1, 2); content.Controls.Add(customer, 0, 1);
        TableLayoutPanel options = new() { Dock = DockStyle.Fill, AutoSize = true, ColumnCount = 2, RowCount = 1 }; options.ColumnStyles.Add(new ColumnStyle(SizeType.Percent, 50)); options.ColumnStyles.Add(new ColumnStyle(SizeType.Percent, 50));
        GroupBox drinks = Choices("Nước uống", rdoCafeDen, "Cafe đen", rdoCafeDa, "Cafe đá", rdoCafeSua, "Cafe sữa", rdoCafeSuaDa, "Cafe sữa đá", rdoCafeKem, "Cafe kem"); GroupBox food = Choices("Thức ăn", chkBanhTrung, "Bánh mì trứng", chkBanhCa, "Bánh mì cá", chkMiTomTrung, "Mì tôm trứng", chkMiXaoBo, "Mì xào bò", chkMiCay, "Mì cay"); options.Controls.Add(drinks, 0, 0); options.Controls.Add(food, 1, 0); content.Controls.Add(options, 0, 2);
        FlowLayoutPanel actions = UiLayout.ButtonBar(); btnTinhTien = UiLayout.Button("Tính tiền"); btnNhapLai = UiLayout.Button("Nhập lại"); btnThanhToan = UiLayout.Button("Thanh toán"); Button btnThoat = UiLayout.Button("Thoát"); actions.Controls.AddRange(new Control[] { btnTinhTien, btnNhapLai, btnThanhToan, btnThoat }); content.Controls.Add(actions, 0, 3);
        txtTongKhach.ReadOnly = true; txtTongTien.ReadOnly = true; TableLayoutPanel totals = UiLayout.Fields(2, 30); UiLayout.AddField(totals, 0, "Tổng khách hàng:", txtTongKhach); UiLayout.AddField(totals, 1, "Tổng tiền thanh toán:", txtTongTien); GroupBox summary = new() { Text = "Tổng kết", Dock = DockStyle.Fill, AutoSize = true, Padding = new Padding(10) }; summary.Controls.Add(totals); content.Controls.Add(summary, 0, 4);
        btnTinhTien.Enabled = false; btnNhapLai.Enabled = false; btnThanhToan.Enabled = false; txtTen.TextChanged += (_, _) => CapNhatNut(); txtSoKhach.TextChanged += (_, _) => CapNhatNut(); txtSoKhach.KeyPress += (_, e) => { if (!char.IsControl(e.KeyChar) && !char.IsDigit(e.KeyChar)) e.Handled = true; }; btnTinhTien.Click += (_, _) => TinhTien(); btnNhapLai.Click += (_, _) => ResetNhap(); btnThanhToan.Click += (_, _) => ThanhToan(); btnThoat.Click += (_, _) => Close(); Load += (_, _) => txtTen.Focus();
    }
    private static GroupBox Choices(string title, params object[] entries) { GroupBox group = new() { Text = title, Dock = DockStyle.Fill, AutoSize = true, Padding = new Padding(14), Margin = new Padding(4) }; FlowLayoutPanel list = new() { Dock = DockStyle.Fill, AutoSize = true, FlowDirection = FlowDirection.TopDown, WrapContents = false }; for (int i = 0; i < entries.Length; i += 2) { ButtonBase control = (ButtonBase)entries[i]; control.Text = (string)entries[i + 1]; control.AutoSize = true; control.Margin = new Padding(3); list.Controls.Add(control); } group.Controls.Add(list); return group; }
    private void CapNhatNut() => btnTinhTien.Enabled = !string.IsNullOrWhiteSpace(txtTen.Text) && int.TryParse(txtSoKhach.Text, out int so) && so > 0;
    private void TinhTien() { if (!int.TryParse(txtSoKhach.Text, out int soKhach) || soKhach <= 0) { MessageBox.Show("Số khách không hợp lệ."); return; } decimal tienNuoc = rdoCafeDen.Checked ? 20000 : rdoCafeDa.Checked || rdoCafeSua.Checked ? 25000 : rdoCafeSuaDa.Checked ? 30000 : rdoCafeKem.Checked ? 35000 : -1; if (tienNuoc < 0) { MessageBox.Show("Vui lòng chọn nước uống."); return; } decimal tienThucAn = 0; if (chkBanhTrung.Checked) tienThucAn += 15000; if (chkBanhCa.Checked) tienThucAn += 15000; if (chkMiTomTrung.Checked) tienThucAn += 20000; if (chkMiXaoBo.Checked) tienThucAn += 30000; if (chkMiCay.Checked) tienThucAn += 50000; tienHienTai = (tienNuoc + tienThucAn) * soKhach; if (chkSinhVien.Checked) tienHienTai *= 0.8m; MessageBox.Show($"Khách hàng: {txtTen.Text}\nSố khách: {soKhach}\nThành tiền: {tienHienTai:N0} VNĐ", "Tính tiền"); btnNhapLai.Enabled = true; btnThanhToan.Enabled = true; }
    private void ThanhToan() { int soKhach = int.Parse(txtSoKhach.Text); tongKhach += soKhach; tongTien += tienHienTai; txtTongKhach.Text = tongKhach.ToString(); txtTongTien.Text = tongTien.ToString("N0") + " VNĐ"; btnThanhToan.Enabled = false; ResetNhap(); }
    private void ResetNhap() { txtTen.Clear(); txtSoKhach.Clear(); chkSinhVien.Checked = false; rdoCafeDen.Checked = false; rdoCafeDa.Checked = false; rdoCafeSua.Checked = false; rdoCafeSuaDa.Checked = false; rdoCafeKem.Checked = false; chkBanhTrung.Checked = false; chkBanhCa.Checked = false; chkMiTomTrung.Checked = false; chkMiXaoBo.Checked = false; chkMiCay.Checked = false; tienHienTai = 0; btnTinhTien.Enabled = false; btnNhapLai.Enabled = false; btnThanhToan.Enabled = false; txtTen.Focus(); }
}
